/// كتب صوتية أصلية: 18 كتاباً، في كل كتاب 6 فصول = 108 فصول مكتوبة يدوياً.
/// كل فصل: [المستوى، العنوان، الجمل مفصولة بـ |، المفردات إنجليزي=عربي مفصولة بـ ;، ثم سؤالان بصيغة سؤال^الصحيح^خطأ^خطأ].
library;

import '../core/generators.dart';
import 'library.dart';

class ProBook {
  const ProBook(this.id, this.cat, this.level, this.titleAr, this.chapters);
  final String id;
  final String cat;
  final String level;
  final String titleAr;
  final List<List<String>> chapters;
}

List<ReadingText> proBookTexts(ProBook b) {
  final out = <ReadingText>[];
  for (var i = 0; i < b.chapters.length; i++) {
    final c = b.chapters[i];
    final quiz = <Quiz>[];
    for (var q = 4; q < c.length; q++) {
      final p = c[q].split('^');
      if (p.length < 3) continue;
      final opts = p.sublist(1);
      final shift = (i + q) % opts.length;
      final ordered = [for (var x = 0; x < opts.length; x++) opts[(x + shift) % opts.length]];
      quiz.add(Quiz(p[0], ordered, ordered.indexOf(p[1])));
    }
    final vocab = <Vocab>[];
    for (final v in c[3].split(';')) {
      final kv = v.split('=');
      if (kv.length == 2) vocab.add(Vocab(kv[0], kv[1]));
    }
    out.add(ReadingText(id: '${b.id}_${i + 1}', cat: b.cat, level: b.level, title: c[1], lines: c[2].split('|'), vocab: vocab, quiz: quiz));
  }
  return out;
}

